import React from 'react';
import loadable from '@loadable/component';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

// Components
import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
import { routes as _routes } from '@salesforce/retail-react-app/app/routes';
import { RECENTLY_VIEWED_ROUTE } from 'app/constants';

const fallback = <Skeleton height="75vh" width="100%" />;
// Base routes deliberately not served. `scripts/generateRegistry.mjs` reads this list so the
// route registry matches runtime; keep it a literal array of strings.
const EXCLUDED_BASE_ROUTES = ['/category/:categoryId'];

// Create your pages here and add them to the routes array
// Use loadable to split code into smaller js chunks
const Home = loadable(() => import('./pages/home'), { fallback });
const MyNewRoute = loadable(() => import('./pages/my-new-route'));
const ContentfulPreview = loadable(() => import('./pages/contentfulPreview'), { fallback });
const CheckoutError = loadable(() => import('./pages/checkout-error'), { fallback });
const CheckoutRedirect = loadable(() => import('./pages/checkout-redirect'), { fallback });
/*
 * Same trap as ProductDetail/ProductList: the base app/routes.jsx loads the confirmation page
 * with a relative import that the overrides resolver never redirects. Without this explicit
 * entry the Adyen confirmation override is dead code and the base page renders instead.
 */
const CheckoutConfirmation = loadable(() => import('./pages/confirmation'), { fallback });

/*
 * The PDP override is reached through this explicit entry, not through the overrides
 * resolver. That resolver only redirects imports that *name* `@salesforce/retail-react-app`;
 * the base `app/routes.jsx` loads its PDP with a relative `import('./pages/product-detail')`,
 * which is never redirected. Without the route below, `overrides/app/pages/product-detail`
 * is dead code and the base page renders instead.
 */
const ProductDetail = loadable(() => import('./pages/product-detail'), { fallback });

// Same trap as ProductDetail above: the base app/routes.jsx loads PLP with a relative
// `import('./pages/product-list')`, which the overrides resolver never redirects. Without the
// two routes below, `overrides/app/pages/product-list` is dead code and the base page renders
// instead. Base routes.jsx uses this same component for both '/search' and
// '/category/:categoryId' — mirrored here as two entries pointing at the one override.
const ProductList = loadable(() => import('./pages/product-list'), { fallback });

// Hierarchical category URLs (/clothing/dresses/day-dresses, SEO PRD DMU-014): the dispatcher
// resolves any unmatched path to a category (PLP), a single-segment Contentful experience page, or
// not-found. The base '/category/:categoryId' shape is not served at all — see `..._routes` below.
const CategoryPath = loadable(() => import('./pages/categoryPath'), { fallback });

// SFCC-84 Recently Viewed Full History page (build plan §B2) — a genuinely new route, not an
// override of any base page, so there is no relative-vs-package-path trap like ProductDetail/
// ProductList above.
const RecentlyViewed = loadable(() => import('./pages/recentlyViewed'), { fallback });

const routes = [
  {
    path: '/',
    component: Home,
    exact: true,
  },
  {
    path: '/my-new-route',
    component: MyNewRoute,
  },
  // Must precede `..._routes` — the base array carries its own '/product/:productId'
  // entry pointing at the base page, and `configureRoutes` keeps the first match.
  {
    path: '/product/:productId',
    component: ProductDetail,
  },
  // Same reasoning as ProductDetail above — the base array carries its own '/search' entry
  // pointing at the base page, and `configureRoutes` keeps the first match.
  {
    path: '/search',
    component: ProductList,
  },
  { path: '/checkout/confirmation/:orderNo', component: CheckoutConfirmation, exact: true },
  { path: '/checkout/error', component: CheckoutError, exact: true },
  { path: '/checkout/redirect', component: CheckoutRedirect, exact: true },
  // The base '/category/:categoryId' route is dropped rather than shadowed: category pages live
  // at their hierarchical path only, and '/category/...' falls through to CategoryPath's not-found.
  ..._routes.filter((route: { path?: string }) => !EXCLUDED_BASE_ROUTES.includes(route.path ?? '')),
  // Contentful Live Preview — must be before /:slug so it takes priority.
  {
    path: '/preview',
    component: ContentfulPreview,
    exact: true,
  },
  // No ordering constraint versus `..._routes` above — the base array has no '/recently-viewed'
  // entry to shadow. Only requirement: land before the '/:slug' catch-all below.
  {
    path: RECENTLY_VIEWED_ROUTE,
    component: RecentlyViewed,
    exact: true,
  },
  // Category pages and Contentful Studio/Experience pages — fallback after all SFCC routes.
  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no
  // other route matched. CategoryPath renders the Experience page itself for a single-segment path
  // that is not a category.
  {
    path: '/:segments+',
    component: CategoryPath,
  },
];

export default () => {
  const config = getConfig();
  return configureRoutes(routes, config, {
    ignoredRoutes: ['/callback', '*'],
  });
};

